  border-spacing: 0 0;
  color: var(--code-color);
  font-family: var(--code-font-family);
  font-size: 0.68rem;
}

.code-snippet td {
  padding: 0;
  text-align: left;
}

td.line_no {
  color: var(--code-color-light);
  min-width: 4ch;
  padding-right: 20px;
  text-align: right;
  user-select: none;
}

td.code_line {
  width: 99%;
}

tr.executed-line {
  background-color: var(--code-background-color-dark);
}

.cause-wrapper {
  margin-top: 50px;
